import json, os, shutil
from datetime import datetime, timezone
def usage(p):
    try:
        t, u, f = shutil.disk_usage(p)
        return round(u / t * 100, 1), round(t / 2**30, 1), round(u / 2**30, 1)
    except Exception:
        return None, None, None
root_pct, root_total, root_used = usage('/')
home_pct, _, _ = usage('/home/imae')
try:
    load1 = round(os.getloadavg()[0], 2)
except Exception:
    load1 = None
mem = {}
try:
    with open('/proc/meminfo') as f:
        for line in f:
            k, v = line.split(':')
            mem[k.strip()] = int(v.strip().split()[0]) // 1024
except Exception:
    pass
try:
    dl_count = len(os.listdir('/home/imae/Downloads'))
except Exception:
    dl_count = 0
print(json.dumps([{"json": {
    "at": datetime.now(timezone.utc).isoformat(),
    "disk_root_pct": root_pct, "disk_root_total_gb": root_total, "disk_root_used_gb": root_used,
    "disk_home_pct": home_pct, "load1": load1,
    "mem_total_mb": mem.get("MemTotal"), "mem_avail_mb": mem.get("MemAvailable"),
    "downloads_count": dl_count,
}}]))
